SET secret_payload = CAST(#{params.SecretPayload,sensitive=true} AS jsonb),
    updated_at = NOW()
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_external_id = #{params.SessionExternalID}
AND external_id = #{params.ResourceExternalID}
AND resource_type = 'github_repository'
AND deleted_at IS NULL
RETURNING

UPDATE session_resources
SET deleted_at = COALESCE(deleted_at, NOW()), updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND file_ownership IS DISTINCT FROM 'owned'
AND (
    (resource_type = 'file' AND file_ownership = 'referenced')
    OR resource_type IN ('github_repository', 'memory_store')
)
AND deleted_at IS NULL

