INSERT INTO session_resources (
uuid, external_id, organization_uuid, workspace_uuid, session_uuid,
session_external_id, resource_type, secret_payload,
path, parent_path, file_uuid, file_ownership, created_at, updated_at
)
SELECT #{params.ResourceUUID}, #{params.ResourceExternalID},
session.organization_uuid, session.workspace_uuid, session.uuid,
session.external_id, 'skill_archive', NULL,
#{params.EntryPath}, '/skills', #{params.FileUUID}, NULL, #{params.Now}, #{params.Now}
FROM sessions session
WHERE session.uuid = #{params.SessionUUID}
AND session.workspace_uuid = #{params.WorkspaceUUID}
AND session.deleted_at IS NULL
